/** What had to be resolved before this list could be seeded honestly. */
export const HURFORDS_TIMBER_AUDIT: { topic: string; note: string }[] = [
  { topic: "The $80", note: "The workbook calls it a Job Lot Fee and describes it two incompatible ways in one row: $80 'once per order' and $80 'when quantity for that product is less than one full pallet'. On a three-line order short of a pallet the second reading bills $240. Damien settled it: it is a BROKEN PACK FEE, $80 once on an order that does not make a full pallet, and delivery to the Nerang warehouse is free with no minimum. This corrects an earlier reading of the same $80 as a flat delivery charge on every order, so an all-full-pallet order now carries nothing. It never multiplies by the short lines, and a full-pallet line does not escape it when it shares an order with a short line, because the test is whether the order makes a pallet. Seeded once as a handling fee rule, never as a per-product charge." },
  { topic: "Pallet Price column heading", note: "The rate column is headed 'Pallet Price $/m2', which reads like the cheaper half of a pallet/broken-pallet pair. No second rate is printed on the list and none was confirmed, so one rate is seeded for every quantity with no cut rate and no volume break. The heading makes sense under the corrected fee reading: it is the pallet rate, and going under a pallet costs the $80 broken pack fee rather than a higher rate per m2. If Hurford's ever quote a broken-pallet rate it goes in cutCostPrice." },
  { topic: "Full Pallet m2 column", note: "Printed blank on all 163 rows, so it is derived as pieces a box x board m2 x boxes a pallet. Ranges from 69.12 to 119.808 m2 a pallet." },
  { topic: "First Floors 135mm is two floors, not one", note: "Blackbutt and Spotted Gum are each published twice under the one range name at the same 135mm width and the same two board lengths: 14mm with a 4mm lamella and a UV Craft Oil / UV Lacquer finish at $88/m2, and 13.5mm non brushed with no lamella printed at $81/m2. Same box m2, same boxes a pallet, $7/m2 apart. Range and colour alone collide on these 4 rows, so the thickness is in the variant key and each row names its rival spec. The 4 rows with no lamella on the whole list are exactly these 13.5mm ones." },
  { topic: "Price age", note: "Effective 1 April 2025, about 18 months old at seed time. Damien confirmed the rates are still current, so they are seeded as they stand with no stale-price flag." },
];

